window.__votdWeek && window.__votdWeek({"week":"2028-05-15","reading":"Mosiah 18–24","days":[{"d":"2028-05-15","ref":"Mosiah 18:10","b":"Mosiah","c":18,"v":10,"he":"וְעַתָּה אֹמֵר אֲנִי לָכֶם אִם־זֶה חֵפֶץ לְבַבְכֶם מַה־לָּכֶם כִּי־לֹא תִטָּבְלוּ בְּשֵׁם יְהוָה לְעֵדוּת לְפָנָיו כִּי בָּאתֶם בִּבְרִית לְעׇבְדוֹ וְלִשְׁמֹר מִצְוֹתָיו לְמַעַן יִשְׁפֹּךְ רוּחוֹ עֲלֵיכֶם בְּיֶתֶר שְׂאֵת׃","en":"Now I say unto you, if this be the desire of your hearts, what have you against being baptized in the name of the Lord, as a witness before him that ye have entered into a covenant with him, that ye will serve him and keep his commandments, that he may pour out his Spirit more abundantly upon you?"},{"d":"2028-05-16","ref":"Mosiah 18:19","b":"Mosiah","c":18,"v":19,"he":"וַיְצַוֵּם לְבִלְתִּי לַמֵּד דָּבָר זוּלַת הַדְּבָרִים אֲשֶׁר לִמְּדָם וַאֲשֶׁר נֶאֶמְרוּ בְּפִי נְבִיאֵי הַקֹּדֶשׁ׃","en":"And he commanded them that they should teach nothing save it were the things which he had taught, and which had been spoken by the mouth of the holy prophets."},{"d":"2028-05-17","ref":"Mosiah 21:4","b":"Mosiah","c":21,"v":4,"he":"הֵן כׇּל־זֹאת נֶעֶשְׂתָה לְמַעַן יִמָּלֵא דְּבַר־יְהוָה׃","en":"Yea, all this was done that the word of the Lord might be fulfilled."},{"d":"2028-05-18","ref":"Mosiah 23:9","b":"Mosiah","c":23,"v":9,"he":"אַךְ זִכְרוּ אֶת־עֲוֹן הַמֶּלֶךְ נֹחַ וְכֹהֲנָיו וְגַם־אֲנִי נִלְכַּדְתִּי בְּמוֹקֵשׁ וָאֶעֱשֶׂה דְבָרִים רַבִּים תּוֹעֵבוֹת בְּעֵינֵי יְהוָה אֲשֶׁר־הֵבִיאוּ עָלַי תְּשׁוּבָה קָשָׁה׃","en":"But remember the iniquity of king Noah and his priests; and I myself was caught in a snare, and did many things which were abominable in the sight of the Lord, which caused me sore repentance;"},{"d":"2028-05-19","ref":"Mosiah 23:21","b":"Mosiah","c":23,"v":21,"he":"וְאוּלָם רָאָה יְהוָה לְנָכוֹן לְיַסֵּר אֶת־עַמּוֹ אַף יִבְחַן אֶת־אֹרֶךְ רוּחָם וֶאֱמוּנָתָם׃","en":"Nevertheless the Lord seeth fit to chasten his people; yea, he trieth their patience and their faith."},{"d":"2028-05-20","ref":"Mosiah 24:12","b":"Mosiah","c":24,"v":12,"he":"וְאַלְמָא וְעַמּוֹ לֹא־הֵרִימוּ קוֹלָם אֶל־יְהוָה אֱלֹהֵיהֶם אַךְ שָׁפְכוּ אֶת־לִבָּם לְפָנָיו וַיֵּדַע אֶת־מַחְשְׁבוֹת לְבָבָם׃","en":"And Alma and his people did not raise their voices to the Lord their God, but did pour out their hearts to him; and he did know the thoughts of their hearts."},{"d":"2028-05-21","ref":"Mosiah 24:17","b":"Mosiah","c":24,"v":17,"he":"וַיֹּאמֶר אֶל־אַלְמָא אַתָּה תֵּלֵךְ לִפְנֵי הָעָם־הַזֶּה וַאֲנִי אֵלֵךְ אִתְּךָ וְאַצִּיל אֶת־הָעָם הַזֶּה מֵעַבְדוּת׃","en":"And he said unto Alma: Thou shalt go before this people, and I will go with thee and deliver this people out of bondage."}]});
